      // ── Step 5: Save to user history ──
      if (user != null) {
        await FirebaseFirestore.instance
            .collection('users').doc(user.uid)
            .collection('selectedProfessionals').add({
          'professionalName': proName,
          'professionalId': proId,
          'specialty': offer['specialty'] ?? '',
          'emoji': offer['emoji'] ?? '🔧',
          'price': offer['price'] ?? 0,
          'message': offer['message'] ?? '',
          'availableFrom': offer['availableFrom'] ?? '',
          'requestDescription': widget.description,
          'requestId': widget.requestId,
          'selectedAt': FieldValue.serverTimestamp(),
        });
      }

      // ── Step 6: Mark request as completed ──
      await FirebaseFirestore.instance
          .collection('requests').doc(widget.requestId)
          .update({
        'status': 'completed',
        'selectedPro': proName.isNotEmpty ? proName : proId.isNotEmpty ? proId : 'selected',
        'offersViewed': true,
      });
      });

      // ── Step 7: Notify professional ──
      if (proId.isNotEmpty) {
        await FirebaseFirestore.instance
            .collection('users').doc(proId)
            .collection('notifications').add({
          'title': '🎉 Αποδέχτηκαν την προσφορά σου!',
          'body': '$userName επέλεξε εσένα!',
          'isRead': false,
          'type': 'offer_accepted',
          'userName': userName,
          'userPhone': userPhone,
          'requestId': widget.requestId,
          'createdAt': FieldValue.serverTimestamp(),
        });
        // FCM push
        try {
          final proUserDoc = await FirebaseFirestore.instance
              .collection('users').doc(proId).get();
          final fcmToken = proUserDoc.data()?['fcmToken'] as String?;
          if (fcmToken != null && fcmToken.isNotEmpty) {
            await http.post(
              Uri.parse('$kBackendUrl/send-push'),
              headers: {'Content-Type': 'application/json'},
              body: jsonEncode({
                'token': fcmToken,
                'title': '🎉 Επέλεξαν εσένα!',
                'body': '$userName αποδέχτηκε την προσφορά σου! Τηλ: $userPhone',
                'data': {
                  'type': 'offer_accepted',
                  'requestId': widget.requestId,
                  'userName': userName,
                  'userPhone': userPhone,
                },
              }),
            ).timeout(const Duration(seconds: 6));
          }
        } catch (_) {}
      }
    } catch (e) {
      debugPrint('Booking error: \$e');
    }
                'userName': userName,
                'userPhone': userPhone,
              },
            }),
          ).timeout(const Duration(seconds: 20));
        }
      } catch (_) {}
